package com.cpf.testkit; import java.util.concurrent.atomic.AtomicReference; public final class CpfFailureSwitch { public enum Mode { HEALTHY, TIMEOUT, FAILURE, UNKNOWN } private final AtomicReference<Mode> mode=new AtomicReference<>(Mode.HEALTHY); public void set(Mode m){mode.set(m);} public Mode get(){return mode.get();} public void check(){switch(mode.get()){case FAILURE->throw new IllegalStateException("injected failure");case TIMEOUT->throw new CpfInjectedTimeoutException();case UNKNOWN->throw new CpfInjectedUnknownException();default->{}}} public static final class CpfInjectedTimeoutException extends RuntimeException{} public static final class CpfInjectedUnknownException extends RuntimeException{} }
